import { ChangeDetectionStrategy, Component, signal } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';

type CommentNode = {
  id: string;
  text: string;
  children: CommentNode[];
};

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [NgTemplateOutlet, FormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly comments = signal<CommentNode[]>([]);

  readonly topDraft = signal('');

  readonly activeReplyId = signal<string | null>(null);
  readonly replyDraft = signal('');

  private nextId = 1;
  private makeId(): string {
    return String(this.nextId++);
  }

  addTop(): void {
    const text = this.topDraft().trim();
    if (!text) return;

    const comment: CommentNode = { id: this.makeId(), text, children: [] };
    this.comments.update((comments) => [comment, ...comments]);
    this.topDraft.set('');
  }

  openReply(id: string): void {
    this.activeReplyId.set(id);
    this.replyDraft.set('');
  }

  cancelReply(): void {
    this.activeReplyId.set(null);
    this.replyDraft.set('');
  }

  submitReply(parentId: string): void {
    const text = this.replyDraft().trim();
    if (!text) return;

    const reply: CommentNode = { id: this.makeId(), text, children: [] };
    this.comments.update((comments) => this.withReply(comments, parentId, reply));
    this.cancelReply();
  }

  // Copy only the path to the parent: the signal gets a new root array, and other subtrees stay the same objects.
  private withReply(nodes: CommentNode[], parentId: string, reply: CommentNode): CommentNode[] {
    let changed = false;
    const next = nodes.map((node) => {
      const children = node.id === parentId
        ? [...node.children, reply]
        : this.withReply(node.children, parentId, reply);
      if (children === node.children) return node;
      changed = true;
      return { ...node, children };
    });
    return changed ? next : nodes;
  }
}
